do $$ declare task uuid:='a0000000-0000-4000-8000-000000000030'; begin
 perform public.create_maintenance(task,'a0000000-0000-4000-8000-000000000020','Broken AC','Air conditioner not cooling','HIGH');
 perform public.create_maintenance(task,'a0000000-0000-4000-8000-000000000020','Broken AC','Air conditioner not cooling','HIGH');
 if (select count(*) from public.maintenance_tasks where id=task)<>1 or (select count(*) from public.maintenance_activity where task_id=task)<>1 then raise exception 'Duplicate report created'; end if;
 begin perform public.create_maintenance(task,'a0000000-0000-4000-8000-000000000020','Different issue','Description','HIGH'); raise exception 'Reused key accepted'; exception when raise_exception then if sqlerrm<>'REQUEST_CONFLICT' then raise; end if; end;
 begin perform public.update_maintenance(task,1,'START'); raise exception 'Unassigned cleaner started job'; exception when insufficient_privilege then null; end;
