 perform public.update_maintenance(task,1,'ASSIGN','a0000000-0000-4000-8000-000000000002');
 begin perform public.update_maintenance(task,1,'START'); raise exception 'Stale update accepted'; exception when raise_exception then if sqlerrm<>'STALE_TASK' then raise; end if; end;
