 begin perform public.update_maintenance(task,4,'COMPLETE',null,'Checked unit'); raise exception 'Cleaner approved own completion'; exception when insufficient_privilege then null; end;
 begin update public.maintenance_tasks set status='COMPLETED' where id=task; raise exception 'Direct update allowed'; exception when insufficient_privilege then null; end;
